def comps(cells, conn8=False):
    cells=set(cells); seen=set(); out=[]
    for c in cells:
        if c in seen: continue
        stack=[c]; comp=[]; seen.add(c)
        while stack:
            i,j=stack.pop(); comp.append((i,j))
            for di in (-1,0,1):
                for dj in (-1,0,1):
                    if di==dj==0: continue
                    if conn8 and abs(di)+abs(dj)==2: continue
                    n=(i+di,j+dj)
                    if n in cells and n not in seen: seen.add(n); stack.append(n)
        out.append(comp)
    return out
